const int NUM_LINES = 20;
vec2 lines[NUM_LINES * 2];

float random(float seed) {
    return fract(sin(seed) * 2832.23) * 1.0 - .5;
}

vec2 randomPoint(float seed) {
    return vec2(random(seed), random(seed + 1.0));
}

void generateLines() {
    for (int i = 0; i < NUM_LINES; i++) {
        float seed = float(i) * 10.0;
        vec2 startPoint = randomPoint(seed);
        vec2 endPoint = randomPoint(seed + 2.0);
        lines[i * 2] = startPoint;
        lines[i * 2 + 1] = endPoint;
    }
}

float lineIntersectionDistance(vec2 p1, vec2 p2, vec2 q1, vec2 q2) {
    vec2 r = p2 - p1;
    vec2 s = q2 - q1;
    float denominator = r.x * s.y - r.y * s.x;
    if (denominator == 0.0) {
        return -1.0;
    }
    vec2 qp = q1 - p1;
    float t = (qp.x * s.y - qp.y * s.x) / denominator;
    float u = (qp.x * r.y - qp.y * r.x) / denominator;
    if (t >= 0.0 && t <= 1.0 && u >= 0.0 && u <= 1.0) {
        vec2 intersection = p1 + t * r;
        return length(intersection - p1);
    }
    return -1.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.x;
    vec2 mp = (iMouse.xy-.5*iResolution.xy)/iResolution.x;
    vec3 col = vec3(0.02 / length(uv - mp)) * vec3(0.8, 0.7, 0);
    generateLines();
    for(int i = 0; i < NUM_LINES-1; i+=2){
        float t = lineIntersectionDistance(uv, mp, lines[i], lines[i+1]);
        if(t > 0.){
            col = vec3(0);
            break;
        }
    }
    fragColor = vec4(col,1.0);
}
